REFERENCE_WORD = "-+++--"
SIGMA = pb.SIGMA
MINUS = (0, 1, 2)
PLUS = (3, 4, 5)


def frac_to_str(v: Fraction) -> str:
    if v.denominator == 1:
        return str(v.numerator)
    return f"{v.numerator}/{v.denominator}"


def copy_source(qdir: Path) -> Tuple[Path, Path]:
